    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule, $skipUnusedClass = false)
    {
        $unusedClass = $skipUnusedClass ? '' : ' sc-grid-order-icon-unused';        if ($this->scIsFieldNumeric($fieldName)) {
            $defaultOffIcon = 'asc' == $this->scGetDefaultFieldOrder($fieldName) ? "fas fa-sort-numeric-down" : "fas fa-sort-numeric-down-alt";
            if ('desc' == $sortRule) {
                return "<span class=\"fas fa-sort-numeric-down-alt sc-grid-order-icon sc-grid-order-fld-{$fieldName}\"></span>";
            } elseif ('asc' == $sortRule) {
                return "<span class=\"fas fa-sort-numeric-down sc-grid-order-icon sc-grid-order-fld-{$fieldName}\"></span>";
            } else {
                return "<span class=\"" . $defaultOffIcon . " sc-grid-order-icon sc-grid-order-fld-{$fieldName}{$unusedClass}\"></span>";
            }
        } else {
            $defaultOffIcon = 'asc' == $this->scGetDefaultFieldOrder($fieldName) ? "fas fa-sort-alpha-down" : "fas fa-sort-alpha-down-alt";
            if ('desc' == $sortRule) {
                return "<span class=\"fas fa-sort-alpha-down-alt sc-grid-order-icon sc-grid-order-fld-{$fieldName}\"></span>";
            } elseif ('asc' == $sortRule) {
                return "<span class=\"fas fa-sort-alpha-down sc-grid-order-icon sc-grid-order-fld-{$fieldName}\"></span>";
            } else {
                return "<span class=\"" . $defaultOffIcon . " sc-grid-order-icon sc-grid-order-fld-{$fieldName}{$unusedClass}\"></span>";
            }
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "evento_id":
                return true;
            case "valor_diaria":
                return true;
            case "valor_taxa":
                return true;
            case "id_geral":
                return true;
            case "hotel":
                return true;
            case "publico":
                return true;
            case "regional":
                return true;
            case "pais":
                return true;
            case "hotel_ida":
                return true;
            case "cia_aerea_ida":
                return true;
            case "origem_ida":
                return true;
            case "destino_ida":
                return true;
            case "hotel_volta":
                return true;
            case "cia_aerea_volta":
                return true;
            case "origem_volta":
                return true;
            case "destino_volta":
                return true;
            case "id_usuario_relato":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "evento_id":
                return 'desc';
            case "data_nascimento":
                return 'desc';
            case "checkin":
                return 'desc';
            case "checkout":
                return 'desc';
            case "data_cadastro":
                return 'desc';
            case "validade_passporte":
                return 'desc';
            case "atualizacao_presenca":
                return 'desc';
            case "dt_confirm_presenca":
                return 'desc';
            case "data_contato":
                return 'desc';
            case "hora_saida_ida":
                return 'desc';
            case "data_saida_ida":
                return 'desc';
            case "data_chegada_ida":
                return 'desc';
            case "hora_chegada_ida":
                return 'desc';
            case "data_saida_volta":
                return 'desc';
            case "hora_saida_volta":
                return 'desc';
            case "data_chegada_volta":
                return 'desc';
            case "hora_chegada_volta":
                return 'desc';
            case "dt_chegada_proprio":
                return 'desc';
            case "hr_chegada_proprio":
                return 'desc';
            case "valor_diaria":
                return 'desc';
            case "valor_taxa":
                return 'desc';
            case "id_geral":
                return 'desc';
            case "hotel":
                return 'desc';
            case "publico":
                return 'desc';
            case "regional":
                return 'desc';
            case "pais":
                return 'desc';
            case "hotel_ida":
                return 'desc';
            case "cia_aerea_ida":
                return 'desc';
            case "origem_ida":
                return 'desc';
            case "destino_ida":
                return 'desc';
            case "hotel_volta":
                return 'desc';
            case "cia_aerea_volta":
                return 'desc';
            case "origem_volta":
                return 'desc';
            case "destino_volta":
                return 'desc';
            case "data_nota_gate":
                return 'desc';
            case "id_usuario_relato":
                return 'desc';
        }
        return 'asc';
    }

