 function NM_grid_data_cadastro()
 {
      global $nm_saida;
      $actionbarFieldLinkHiddenClass = '';
      if (!isset($this->NM_cmp_hidden['data_cadastro']) || $this->NM_cmp_hidden['data_cadastro'] != "off") { 
          $conteudo = NM_encode_input(sc_strip_script($this->data_cadastro)); 
          $conteudo_original = NM_encode_input(sc_strip_script($this->data_cadastro)); 
          if ($conteudo === "") 
          { 
              $conteudo = "&nbsp;" ;  
              $graf = "" ;  
          } 
          else    
          { 
               if (substr($conteudo, 10, 1) == "-") 
               { 
                  $conteudo = substr($conteudo, 0, 10) . " " . substr($conteudo, 11);
               } 
               if (substr($conteudo, 13, 1) == ".") 
               { 
                  $conteudo = substr($conteudo, 0, 13) . ":" . substr($conteudo, 14, 2) . ":" . substr($conteudo, 17);
               } 
               $conteudo_x =  $conteudo;
               nm_conv_limpa_dado($conteudo_x, "YYYY-MM-DD HH:II:SS");
               if (is_numeric($conteudo_x) && $conteudo_x > 0) 
               { 
                   $this->nm_data->SetaData($conteudo, "YYYY-MM-DD HH:II:SS");
                   $conteudo = $this->nm_data->FormataSaida($this->nm_data->FormatRegion("DH", "ddmmaaaa;hhiiss"));
               } 
          } 
          $str_tem_display = $conteudo;
          if(!empty($str_tem_display) && $str_tem_display != '&nbsp;' && !$_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['proc_pdf'] && !$_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['embutida'] && !empty($conteudo)) 
          { 
