       $nm_saida->saida("        }\r\n");
       $nm_saida->saida("        return val;\r\n");
       $nm_saida->saida("     }\r\n");
       $nm_saida->saida("   </script>\r\n");
   }
    function getFieldHighlight($filter_type, $field, $str_value, $str_value_original='')
    {
        $str_html_ini = '<div class="highlight">';
        $str_html_fim = '</div>';

        if($filter_type == 'advanced_search')
        {
            if (
                isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]) &&
                isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond" ]) &&
                !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]) &&
                (
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'qp' ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'eq' ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'ii' ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'aw'
                )
            )
            {
                if($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'qp')
                {
                    if(is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]))
                    {
                        foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ] as $ind => $vals)
                        {
                            if(strcasecmp($vals, $str_value) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            elseif(strcasecmp($vals, $str_value_original) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            else
                            {
                                $keywords = preg_quote($vals, '/');
                                $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                            }
                        }
                    }
                    else
                    {
                        if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ], $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ], $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        else
                        {
                            $keywords = preg_quote($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ], '/');
                            $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                        }
                    }
                }
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'aw')
                {
                    $args  = explode(" ", $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]);
                    foreach ($args as $cada_args) {
                        if (empty($cada_args)) {
                            continue;
                        }
                        if(strcasecmp($cada_args, $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($cada_args, $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        else
                        {
                            $keywords = preg_quote($cada_args, '/');
                            $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                        }
                    }
                }
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'eq')
                {
                    if(is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]))
                    {
                        foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ] as $ind => $vals)
                        {
                            if(strcasecmp($vals, $str_value) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            elseif(strcasecmp($vals, $str_value_original) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                        }
                    }
                    else
                    {
                        if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ], $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ], $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                    }
                }
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field . "_cond"] == 'ii')
                {
                    if(is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]))
                    {
                        foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ] as $ind => $vals)
                        {
                            if(strcasecmp($vals, substr($str_value, 0, strlen($vals))) == 0)
                            {
                                $str_value = $str_html_ini. substr($str_value, 0, strlen($vals)) .$str_html_fim . substr($str_value, strlen($vals));
                            }
                        }
                    }
                    else
                    {
                        if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ], substr($str_value, 0, strlen($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]))) == 0)
                        {
                            $str_value = $str_html_ini. substr($str_value, 0, strlen($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ])) .$str_html_fim . substr($str_value, strlen($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['campos_busca'][ $field ]));
                        }
                    }
                }
            }
        }
        elseif($filter_type == 'filterbuilder')
        {
            if (
                isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['dyn_search']) &&
                !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['dyn_search'])
            )
            {
                foreach($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['dyn_search'] as $_fld)
                {
                    if($_fld['cmp'] == $field)
                    {
                        $vals = (isset($_fld['val_formated'])?$_fld['val_formated']:"");

                        if($_fld['opc'] == 'qp')
                        {
                           if(strcasecmp($vals, $str_value) == 0)
                           {
                              $str_value = $str_html_ini. $str_value .$str_html_fim;
                           }
                           elseif(strcasecmp($vals, $str_value_original) == 0)
                           {
                              $str_value = $str_html_ini. $str_value .$str_html_fim;
                           }
                           else
                           {
                              $keywords = preg_quote($vals, '/');
                              $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                           }
                        }
                        elseif($_fld['opc'] == 'eq')
                        {
                            if(strcasecmp($vals, $str_value) == 0)
                            {
                               $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            elseif(strcasecmp($vals, $str_value_original) == 0)
                            {
                               $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                        }
                        elseif($_fld['opc'] == 'ii')
                        {
                            if(strcasecmp($vals, substr($str_value, 0, strlen($vals))) == 0)
                            {
                                $str_value = $str_html_ini. substr($str_value, 0, strlen($vals)) .$str_html_fim . substr($str_value, strlen($vals));
                            }
                        }


                        elseif($_fld['opc'] == 'aw')
                        {
                            $args  = explode(" ", $vals);
                            foreach ($args as $cada_args) {
                                if (empty($cada_args)) {
                                    continue;
                                }
                                if(strcasecmp($cada_args, $str_value) == 0)
                                {
                                    $str_value = $str_html_ini. $str_value .$str_html_fim;
                                }
                                elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($cada_args, $str_value_original) == 0)
                                {
                                    $str_value = $str_html_ini. $str_value .$str_html_fim;
                                }
                                else
                                {
                                    $keywords = preg_quote($cada_args, '/');
                                    $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                                }
                            }
                        }

                    }
                }
            }
        }
        elseif($filter_type == 'quicksearch')
        {
            if( isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][0]) &&
                (
                    (
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][0] == 'SC_all_Cmp' &&
                    in_array($field, array('evento_id', 'evento_dsc', 'nome_participante', 'tipo_pessoa', 'data_nascimento', 'rg', 'nome_cracha', 'convidado_original', 'nome_substituto', 'acomp_mesmoquarto', 'partici_mesmoquarto', 'hotel_dsc', 'checkin', 'checkout', 'early_checkin', 'late_checkout', 'tamanho_camisa', 'tamanho_calcado', 'empresa', 'cargo', 'departamento', 'grupo', 'publico_dsc', 'regional_dsc', 'data_cadastro', 'logradouro', 'complemento', 'cidade', 'bairro', 'cep', 'uf', 'pais_dsc', 'ddd_tel01', 'tel01', 'ddd_celular', 'celular', 'telefone_internacional', 'passaporte', 'validade_passporte', 'cpf', 'filiacao', 'fumante', 'restricao_alimentar', 'e_mail', 'atualizacao_presenca', 'presenca', 'dt_confirm_presenca', 'presenca_motivo', 'presenca_atendente', 'presenca_obs', 'contato_antendente', 'data_contato', 'motivo_contato', 'obs_contato', 'status_contato', 'hora_saida_ida', 'trecho', 'hotel_ida_dsc', 'comprada_bvt_ida', 'data_saida_ida', 'origem_dsc_ida', 'destino_dsc_ida', 'voo_ida', 'cia_dsc_ida', 'localizador_ida', 'etkt_ida', 'data_chegada_ida', 'hora_chegada_ida', 'status_aereo_ida', 'trecho_volta', 'hotel_volta_dsc', 'hr_transfer_volta', 'comprada_bvt_volta', 'data_saida_volta', 'hora_saida_volta', 'data_chegada_volta', 'hora_chegada_volta', 'origem_dsc_volta', 'destino_dsc_volta', 'cia_dsc_volta', 'voo_volta', 'localizador_volta', 'etkt_volta', 'status_aereo_volta', 'tipo_transfer', 'dt_chegada_proprio', 'hr_chegada_proprio', 'valor_diaria', 'valor_taxa', 'obs_transfer', 'anotacoes', 'id_geral', 'cpf_mestre'))
                    ) ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][0] == $field ||
                    strpos($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][0], $field . '_VLS_') !== false ||
                    strpos($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][0], '_VLS_' . $field) !== false
                )
            )
            {
                if($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][1] == 'qp')
                {
                    if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][2], $str_value) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                    elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][2], $str_value_original) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                    else
                    {
                        $keywords = preg_quote($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][2], '/');
                        $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                    }
                }
/*--- mantis 24102 ---*/
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][1] == 'aw')
                {
                    $args  = explode(" ", $_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][2]);
                    foreach ($args as $cada_args) {
                        if (empty($cada_args)) {
                            continue;
                        }
                        if(strcasecmp($cada_args, $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($cada_args, $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        else
                        {
                            $keywords = preg_quote($cada_args, '/');
                            $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                        }
                    }
                }
/*------*/
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][1] == 'eq')
                {
                    if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][2], $str_value) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                    elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_geral_rsvp_r']['fast_search'][2], $str_value_original) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                }
            }
        }
        return $str_value;
    }
